#!/usr/bin/env python3
"""Fill HWPX template with training feedback data."""

import json
import re
import os

def load_json_data(filepath):
    """Load JSON data from file."""
    with open(filepath, 'r', encoding='utf-8') as f:
        return json.load(f)

def transform_value(key, value):
    """Apply special transformations based on key."""
    if key == '참석자수':
        # Extract digits only (e.g., "32명" -> "32")
        return re.sub(r'[^0-9]', '', str(value))
    elif key == '만족도':
        # Extract numeric score and format as "X.X점 (5.0점 만점)"
        # Input is "4.5/5.0", extract 4.5
        match = re.search(r'([0-9.]+)', str(value))
        if match:
            score = match.group(1)
            return f"{score}점 (5.0점 만점)"
        return value
    elif key == '종합의견':
        # Append suffix
        return str(value) + " 후속 심화반 검토 요망."
    else:
        # Use value directly as string
        return str(value)

def build_replacement_map(data):
    """Build mapping from {{key}} to transformed value."""
    mapping = {}
    for key, value in data.items():
        transformed = transform_value(key, value)
        mapping[f'{{{key}}}'] = transformed
        print(f"  {{ {key} }} -> {transformed}")
    return mapping

def process_xml_file(filepath, replacement_map):
    """Process a single XML file, replacing placeholders."""
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    original_content = content
    had_placeholders = '{{' in content

    # Replace all placeholders
    for placeholder, value in replacement_map.items():
        content = content.replace(placeholder, value)

    # Check if any replacements were made
    if had_placeholders:
        # Remove <hp:linesegarray>...</hp:linesegarray> elements
        # from paragraphs that originally had placeholders
        content = re.sub(r'<hp:linesegarray>.*?</hp:linesegarray>', '', content, flags=re.DOTALL)

    # Verify no {{ remains
    if '{{' in content:
        remaining = re.findall(r'\{\{[^}]+\}\}', content)
        print(f"  WARNING: Remaining placeholders in {filepath}: {remaining}")
        return False

    # Write back if changed
    if content != original_content:
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(content)
        print(f"  Processed: {filepath}")
    else:
        print(f"  No changes: {filepath}")

    return True

def main():
    # Paths
    json_path = '/root/training_feedback.json'
    hwpx_work_dir = '/root/hwpx_work'

    # Load JSON data
    print("Loading JSON data...")
    data = load_json_data(json_path)

    # Build replacement map
    print("\nBuilding replacement map:")
    replacement_map = build_replacement_map(data)

    # Find and process XML files
    print("\nProcessing XML files...")
    xml_files = []
    for root, dirs, files in os.walk(hwpx_work_dir):
        for filename in files:
            if filename.endswith('.xml'):
                filepath = os.path.join(root, filename)
                xml_files.append(filepath)

    all_success = True
    for filepath in xml_files:
        success = process_xml_file(filepath, replacement_map)
        if not success:
            all_success = False

    if all_success:
        print("\nAll files processed successfully!")
    else:
        print("\nSome files had issues!")
        return 1

    return 0

if __name__ == '__main__':
    exit(main())

